16	/// An error during execution of an SQL statement.
17	#[derive(thiserror::Error, Debug)]
18	pub enum StmtError {
19	    #[error("SQL string could not be parsed: {source}")]
20	    SqlParse { source: anyhow::Error },
21	    #[error("SQL string does not contain any statement")]
22	    SqlNoStmt,
23	    #[error("SQL string contains more than one statement")]
24	    SqlManyStmts,
25	    #[error("Arguments do not match SQL parameters: {source}")]
26	    ArgsInvalid { source: anyhow::Error },
27	    #[error("Specifying both positional and named arguments is not supported")]
28	    ArgsBothPositionalAndNamed,
29	
30	    #[error("Transaction timed out")]
31	    TransactionTimeout,
32	    #[error("Server cannot handle additional transactions")]
33	    TransactionBusy,
34	    #[error("SQLite error: {message}")]
35	    SqliteError {
36	        source: rusqlite::ffi::Error,
37	        message: String,
38	    },
39	    #[error("SQL input error: {message} (at offset {offset})")]
40	    SqlInputError {
41	        source: rusqlite::ffi::Error,
42	        message: String,
43	        offset: i32,
44	    },
45	
46	    #[error("Operation was blocked{}", .reason.as_ref().map(|msg| format!(": {}", msg)).unwrap_or_default())]
47	    Blocked { reason: Option<String> },
48	    #[error("Response is too large")]
49	    ResponseTooLarge,
50	    #[error("error executing a request on the primary: {0}")]
51	    Proxy(String),
52	}
