54	pub async fn execute_stmt(
55	    db: &impl Connection,
56	    auth: Authenticated,
57	    query: Query,
58	    replication_index: Option<FrameNo>,
59	) -> Result<proto::StmtResult> {
60	    let builder = SingleStatementBuilder::default();
61	    let stmt_res = db
62	        .execute_batch(vec![query], auth, builder, replication_index)
63	        .await
64	        .map_err(catch_stmt_error)?;
65	    stmt_res.into_ret().map_err(catch_stmt_error)
66	}
