68	pub async fn describe_stmt(
69	    db: &impl Connection,
70	    auth: Authenticated,
71	    sql: String,
72	    replication_index: Option<FrameNo>,
73	) -> Result<proto::DescribeResult> {
74	    match db.describe(sql, auth, replication_index).await? {
75	        Ok(describe_response) => Ok(proto_describe_result_from_describe_response(
76	            describe_response,
77	        )),
78	        Err(sqld_error) => match stmt_error_from_sqld_error(sqld_error) {
79	            Ok(stmt_error) => bail!(stmt_error),
80	            Err(sqld_error) => bail!(sqld_error),
81	        },
82	    }
83	}
