85	pub fn proto_stmt_to_query(
86	    proto_stmt: &proto::Stmt,
87	    sqls: &HashMap<i32, String>,
88	    version: Version,
89	) -> Result<Query> {
90	    let sql = proto_sql_to_sql(proto_stmt.sql.as_deref(), proto_stmt.sql_id, sqls, version)?;
91	
92	    let mut stmt_iter = Statement::parse(sql);
93	    let stmt = match stmt_iter.next() {
94	        Some(Ok(stmt)) => stmt,
95	        Some(Err(err)) => bail!(StmtError::SqlParse { source: err }),
96	        None => bail!(StmtError::SqlNoStmt),
97	    };
98	
99	    if stmt_iter.next().is_some() {
100	        bail!(StmtError::SqlManyStmts)
101	    }
102	
103	    let params = if proto_stmt.named_args.is_empty() {
104	        let values = proto_stmt
105	            .args
106	            .iter()
107	            .map(proto_value_to_value)
108	            .collect::<Result<Vec<_>, _>>()?;
109	        Params::Positional(values)
110	    } else if proto_stmt.args.is_empty() {
111	        let values = proto_stmt
112	            .named_args
113	            .iter()
114	            .map(|arg| {
115	                proto_value_to_value(&arg.value).map(|arg_value| (arg.name.clone(), arg_value))
116	            })
117	            .collect::<Result<HashMap<_, _>, _>>()?;
118	        Params::Named(values)
119	    } else {
120	        bail!(StmtError::ArgsBothPositionalAndNamed)
121	    };
122	
123	    let want_rows = proto_stmt.want_rows.unwrap_or(true);
124	    Ok(Query {
125	        stmt,
126	        params,
127	        want_rows,
128	    })
129	}
