131	pub fn proto_sql_to_sql<'s>(
132	    proto_sql: Option<&'s str>,
133	    proto_sql_id: Option<i32>,
134	    sqls: &'s HashMap<i32, String>,
135	    version: Version,
136	) -> Result<&'s str, ProtocolError> {
137	    if proto_sql_id.is_some() && version < Version::Hrana2 {
138	        return Err(ProtocolError::NotSupported {
139	            what: "`sql_id`",
140	            min_version: Version::Hrana2,
141	        });
142	    }
143	
144	    match (proto_sql, proto_sql_id) {
145	        (Some(sql), None) => Ok(sql),
146	        (None, Some(sql_id)) => match sqls.get(&sql_id) {
147	            Some(sql) => Ok(sql),
148	            None => Err(ProtocolError::SqlNotFound { sql_id }),
149	        },
150	        (Some(_), Some(_)) => Err(ProtocolError::SqlIdAndSqlGiven),
151	        (None, None) => Err(ProtocolError::SqlIdOrSqlNotGiven),
152	    }
153	}
154	
155	fn proto_value_to_value(proto_value: &proto::Value) -> Result<Value, ProtocolError> {
156	    Ok(match proto_value {
157	        proto::Value::None => return Err(ProtocolError::NoneValue),
158	        proto::Value::Null => Value::Null,
