197	    pub(crate) fn explicit_transaction(&self) -> crate::hrana::Result<(bool, bool)> {
198	        let mut begin = false; // batch contains BEGIN transaction
199	        let mut end = false; // batch contains COMMIT/ROLLBACK
200	        for step in self.steps.iter() {
201	            if let Some(Ok(parsed)) = crate::parser::Statement::parse(&step.stmt.sql).next() {
202	                match parsed.kind {
203	                    StmtKind::TxnBegin | StmtKind::TxnBeginReadOnly => {
204	                        begin = true;
205	                        end = false;
206	                    }
207	                    StmtKind::TxnEnd => {
208	                        end = true;
209	                        begin = false;
210	                    }
211	                    _ => {}
212	                }
213	            }
214	        }
215	        Ok((begin, end))
216	    }
