222	    pub fn from_iter(stmts: impl IntoIterator<Item = Stmt>, protocol_v3: bool) -> Self {
223	        let mut batch = Batch::new();
224	        let mut step = -1;
225	        for stmt in stmts.into_iter() {
226	            let cond = if step >= 0 {
227	                let mut cond = BatchCond::Ok { step };
228	                if protocol_v3 {
229	                    cond = BatchCond::And {
230	                        conds: vec![cond, BatchCond::IsAutocommit],
231	                    };
232	                }
233	                Some(cond)
234	            } else {
235	                None
236	            };
237	            batch.step(cond, stmt);
238	            step += 1;
239	        }
240	        batch
241	    }
